{"scenarios": [
{"obligation_avoided": "Protection of Confidential Information disclosed after the two-year term, which the company may assume continues for 120 months", "segments": [80, 81], "quotes": ["This Agreement shall remain in effect for a two-year term", "the parties' duty to hold in confidence Confidential Information that was disclosed during term shall remain in effect for one hundred twenty (120) months after termination of this Agreement"], "how": "Information the Recipient receives after the agreement's term ends is not within the 120-month duty, which covers only information disclosed during the term. The Recipient can argue that later disclosures carry no confidentiality duty.", "loophole_type": "short_term"},
{"obligation_avoided": "Restriction on the Receiving Party working for or assisting businesses that compete with the company", "segments": [78], "quotes": ["For a period of twenty-four (24) months after the termination of this Agreement, the Receiving Party shall not engage in, or assist any person in, any business that competes with the business of the Disclosing Party."], "how": "The non-compete ends after 24 months, while confidentiality lasts 120 months. The Recipient can plan to compete once the 24-month window closes and rely on the longer period only for use of the information itself.", "loophole_type": "short_term"},
{"obligation_avoided": "Protection of trade secrets against disclosure by an employee who is the Recipient", "segments": [77], "quotes": ["An individual shall not be held criminally or civilly liable under any federal or state trade secret law for the disclosure of a trade secret that is made in confidence to a federal, state, or local government official, either directly or indirectly, or to an attorney, solely for the purpose of reporting or investigating a suspected violation of law."], "how": "An employee-Recipient can characterize a disclosure of trade secrets as a report of a suspected violation of law to any government official or to an attorney. This immunity is not tied to any agency request, so it works as a broad carve-out for trade secrets.", "loophole_type": "unlimited_carve_out"},
{"obligation_avoided": "Restriction on reverse engineering the company's products and information", "segments": [55], "quotes": ["The Receiving Party shall not reverse engineer any objects which embody the Disclosing Party's Confidential Information."], "how": "The bar covers only objects that embody Confidential Information. The Recipient can analyze behavior or information it can observe without holding a physical object, and argue that this is outside the restriction.", "loophole_type": "other"},
{"obligation_avoided": "Protection of information the Recipient obtains from a third party", "segments": [69], "quotes": ["was received by the Recipient without breach of this Agreement from a third party without restriction as to the use and disclosure of the Discloser's Confidential Information"], "how": "If the Recipient gets the information from a third party that imposed no restriction, the information falls outside the NDA, even when the source was the company's own downstream recipient. The Recipient can use the information without asking the company, provided the third party is not bound.", "loophole_type": "other"}
]}
